require dirname(__DIR__).'/vendor/autoload.php';require_once dirname(__DIR__).'/storage.php';require dirname(__DIR__).'/db.php';
$manifest=json_decode((string)file_get_contents($argv[1]),true,512,JSON_THROW_ON_ERROR);$source=realpath($argv[2]);if($source===false||!is_file($source))throw new RuntimeException('Source PDF not found.');validateUploadedDocument($source,'pdf',['pdf']);
foreach(['program_code','title','version_label']as$key)if(trim((string)($manifest[$key]??''))==='')throw new RuntimeException("Missing $key.");
$find=$conn->prepare('SELECT id FROM program_specifications WHERE program_code=:code ORDER BY id DESC LIMIT 1');$find->execute([':code'=>$manifest['program_code']]);$program=(int)$find->fetchColumn();if(!$program)throw new RuntimeException('Program specification not found for code '.$manifest['program_code']);
$hash=hash_file('sha256',$source);$key='program_manuals/'.$hash.'.pdf';ensureStorageDirectory('program_manuals');$dest=storagePath($key);if(!is_file($dest)&&!copy($source,$dest))throw new RuntimeException('Could not preserve source PDF.');
$fields=['program_specification_id'=>$program,'supersedes_manual_id'=>$manifest['supersedes_manual_id']??null,'title'=>$manifest['title'],'version_label'=>$manifest['version_label'],'academic_period'=>$manifest['academic_period']??null,'declared_program_name'=>$manifest['declared_program_name']??null,'declared_credit_hours'=>$manifest['declared_credit_hours']??null,'declared_semesters'=>$manifest['declared_semesters']??null,'declared_plo_count'=>$manifest['declared_plo_count']??null,'declared_course_count'=>$manifest['declared_course_count']??null,'status'=>$manifest['status']??'Draft','prepared_by'=>$manifest['prepared_by']??null,'approved_by'=>$manifest['approved_by']??null,'updated_date'=>$manifest['updated_date']??null,'approval_date'=>$manifest['approval_date']??null,'next_review_date'=>$manifest['next_review_date']??null,'source_original_name'=>safeDownloadName(basename($source)),'source_storage_key'=>$key,'source_sha256'=>$hash,'source_mime'=>'application/pdf','source_size'=>filesize($source),'created_by_user_id'=>null];
